script:
frappe.ui.form.on('Quotation', {
    refresh: function(frm) {
        frm.set_df_property('items', 'hidden', 1);
        toggle_pet_view(frm);
    },
    custom_is_group: function(frm) {
        toggle_pet_view(frm);
    },
    custom_is_admitted: function(frm) {
        toggle_admissions(frm);
    }
});

function toggle_pet_view(frm) {
    const is_group = frm.doc.custom_is_group;

    const original_fields = [
        'custom_patient_name', 'custom_colour', 'custom_sex',
        'custom_date_of_birth', 'custom_hyd', 'custom_column_break_1',
        'custom_differential_diagnosis', 'custom_species', 'custom_breed',
        'custom_hr', 'custom_rr', 'custom_column_break_2',
        'custom_medication_receipt_no', 'custom_weight', 'custom_crt',
        'custom_medicals_section', 'custom_diagnosis', 'custom_advices',
        'custom_column_break_3', 'custom_complaint', 'custom_patient_owner'
    ];

    const inline_fields = [
        'custom_inline_section_patient', 'custom_inline_col1',
        'custom_inline_patient_name', 'custom_inline_patient_owner',
        'custom_inline_sex', 'custom_inline_col2', 'custom_inline_dob',
        'custom_inline_species', 'custom_inline_follow_up',
        'custom_inline_col3', 'custom_inline_breed', 'custom_inline_colour',
        'custom_inline_section_exam', 'custom_inline_hyd', 'custom_inline_col4',
        'custom_inline_weight', 'custom_inline_col5', 'custom_inline_crt',
        'custom_inline_col6', 'custom_inline_rr', 'custom_inline_col7',
        'custom_inline_hr', 'custom_inline_section_medicals',
        'custom_inline_diff_diagnosis', 'custom_inline_diagnosis',
        'custom_inline_col8', 'custom_inline_complaint', 'custom_inline_advices'
    ];

    const table_fields = [
        'custom_section_break_fgfm3',
        'custom_pet_details'
    ];

    original_fields.forEach(f => frm.set_df_property(f, 'hidden', 1));
    inline_fields.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 1 : 0));
    table_fields.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 0 : 1));

    frm.set_df_property('custom_follow_up_date', 'hidden', is_group ? 0 : 1);
    frm.set_df_property('custom_inline_next_follow_up_date', 'hidden', is_group ? 1 : 0);
    frm.set_df_property('items', 'hidden', 1);

    frm.set_df_property('custom_is_admitted', 'hidden', 0);

    toggle_admissions(frm);
    frm.refresh_fields();
}

function toggle_admissions(frm) {
    const is_group = frm.doc.custom_is_group;
    const is_admitted = frm.doc.custom_is_admitted;

    // Table - only when is_group checked
    const table_adm = [
        'custom_admissions_section',
        'custom_admissions_table'
    ];

    // Inline fields - when is_group unchecked
    const inline_adm = [
        'custom_inline_admissions_section', 'custom_inline_adm_patient',
        'custom_inline_adm_bed', 'custom_inline_adm_col1',
        'custom_inline_adm_doctor', 'custom_inline_adm_checkin',
        'custom_inline_adm_col2', 'custom_inline_adm_checkout'
    ];

    if (is_admitted) {
        // Show table only when is_group checked
        table_adm.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 0 : 1));
        // Show inline only when is_group unchecked
        inline_adm.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 1 : 0));
    } else {
        // Hide both when is_admitted unchecked
        table_adm.forEach(f => frm.set_df_property(f, 'hidden', 1));
        inline_adm.forEach(f => frm.set_df_property(f, 'hidden', 1));
    }

    frm.refresh_fields();
}

frappe.ui.form.on('Quotation', {
    customer_name: function(frm) {
        // Clear invoice when customer changes
        frm.set_value('custom_medication_receipt_no', '');

        // Set query filter for the invoice field
        frm.set_query('custom_medication_receipt_no', function() {
            return {
                filters: {
                    customer: frm.doc.customer_name,
                    docstatus: 1 // optionally show only submitted invoices
                }
            };
        });
    },

    // Also run on form load so the filter works if customer already selected
    refresh: function(frm) {
        if (frm.doc.customer_name) {
            frm.set_query('custom_medication_receipt_no', function() {
                return {
                    filters: {
                        customer: frm.doc.customer_name,
                        docstatus: 1
                    }
                };
            });
        }
    }
});

frappe.ui.form.on('Quotation', {
    // Trigger when customer changes
    customer_name: function(frm) {
        // Loop through existing child rows and reset patient_name
        if (frm.doc.custom_pet_details) {
            frm.doc.custom_pet_details.forEach(row => {
                row.patient_name = '';
            });
            frm.refresh_field('custom_pet_details');
        }

        // Set query for child table field
        frm.fields_dict['custom_pet_details'].grid.get_field('patient_name').get_query = function(doc, cdt, cdn) {
            const row = locals[cdt][cdn];
            return {
                filters: {
                    patient_owner: frm.doc.party_name
                }
            };
        };
    },

    // Also run on form load in case customer is pre-filled
    refresh: function(frm) {
        if (frm.doc.party_name) {
            frm.fields_dict['custom_pet_details'].grid.get_field('patient_name').get_query = function(doc, cdt, cdn) {
                return {
                    filters: {
                        patient_owner: frm.doc.party_name
                    }
                };
            };
        }
    }
});

frappe.ui.form.on("Quotation", {
    refresh(frm) {
        const grid = frm.fields_dict["custom_pet_details"]?.grid;
        if (!grid) return;

        const fieldname = "patient_name";

        grid.grid_rows.forEach(row => {
            if (!row || !row.doc) return;  // <<< safety check

            const field = row.fields_dict[fieldname];
            if (!field || field.__create_new_hooked) return;

            const parent_customer = frm.doc.customer;
            const parent_customer_name = frm.doc.customer_name;

            const original_create_new_doc = field.create_new_doc;
            field.create_new_doc = function(value) {
                console.log("Bro, creating new Patient Name!", row.doc);

                frappe.new_doc("Patient Name", {
                    patient_owner: parent_customer || "Pos Customer",
                    patient_owner_name: parent_customer_name || "",
                    patient_name: value
                });
            };

            field.__create_new_hooked = true;
        });
    },
    custom_inline_patient_name: function(frm) {
        if (frm.doc.custom_inline_patient_name) {
            frappe.db.get_doc('Patient Name', frm.doc.custom_inline_patient_name)
                .then(doc => {
                    frm.set_value('custom_inline_patient_owner', doc.patient_owner);
                    frm.set_value('custom_inline_sex', doc.sex);
                    frm.set_value('custom_inline_dob', doc.dob);
                    frm.set_value('custom_inline_species', doc.species);
                    frm.set_value('custom_inline_breed', doc.breed);
                    frm.set_value('custom_inline_colour', doc.colour);
                });
        }
    }
});

frappe.ui.form.on('Pet Details', {
    patient_name: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.patient_name) {
            frappe.db.get_doc('Patient Name', row.patient_name)
                .then(doc => {
                    frappe.model.set_value(cdt, cdn, 'patient_owner', doc.patient_owner);
                    frappe.model.set_value(cdt, cdn, 'sex', doc.sex);
                    frappe.model.set_value(cdt, cdn, 'date_of_birth', doc.dob);
                    frappe.model.set_value(cdt, cdn, 'species', doc.species);
                    frappe.model.set_value(cdt, cdn, 'breed', doc.breed);
                    frappe.model.set_value(cdt, cdn, 'colour', doc.colour);
                });
        }
    }
});

frappe.ui.form.on('Quotation', {
    refresh: function(frm) {
        frm.set_df_property('custom_procedures_tab', 'hidden', 0);
        frm.set_df_property('custom_vaccinations_tab', 'hidden', 0);
        frm.set_df_property('custom_procedures_html', 'hidden', 0);
        frm.set_df_property('custom_vaccinations_html', 'hidden', 0);
        frm.set_df_property('items', 'hidden', 1);
        toggle_pet_view(frm);
        update_medication_filters(frm);
        render_medical_tabs(frm);
        setup_grid_create_new(frm);
        setup_pet_details_grid(frm);
    },
    customer_name: function(frm) {
        reset_patient_filters(frm);
        update_medication_filters(frm);
    },
    custom_is_group: function(frm) {
        toggle_pet_view(frm);
        render_medical_tabs(frm);
        setup_pet_details_grid(frm);
    },
    custom_is_admitted: function(frm) {
        toggle_admissions(frm);
    },
    custom_inline_patient_name: function(frm) {
        fetch_patient_details(frm);
    },
    custom_procedures_tab: function(frm) {
        render_medical_tabs(frm);
    },
    custom_vaccinations_tab: function(frm) {
        render_medical_tabs(frm);
    }
});

function setup_pet_details_grid(frm) {
    try {
        var grid = frm.fields_dict['custom_pet_details'] && frm.fields_dict['custom_pet_details'].grid;
        if (!grid) return;
        var cols = ['patient_name','patient_owner','sex','date_of_birth','species','breed','colour','follow_up_date','hyd','weight','crt','rr','hr','differential_diagnosis','diagnosis','complaint','advices'];
        grid.visible_columns = undefined;
        cols.forEach(function(fn) {
            var df = frappe.meta.get_docfield("Pet Details", fn);
            if (df) { df.in_list_view = 1; df.hidden = 0; df.read_only = 0; }
        });
        grid.refresh();
    } catch(e) {
        console.warn('setup_pet_details_grid error:', e);
    }
}

function setup_grid_create_new(frm) {
    try {
        const grid = frm.fields_dict["custom_pet_details"]?.grid;
        if (!grid) return;
        grid.grid_rows.forEach(row => {
            if (!row || !row.doc || !row.fields_dict) return;
            const field = row.fields_dict["patient_name"];
            if (!field || field.__create_new_hooked) return;
            field.create_new_doc = function(value) {
                frappe.new_doc("Patient Name", {
                    patient_owner: frm.doc.customer || "Pos Customer",
                    patient_owner_name: frm.doc.customer_name || "",
                    patient_name: value
                });
            };
            field.__create_new_hooked = true;
        });
    } catch(e) {
        console.warn("setup_grid_create_new error:", e);
    }
}

function render_medical_tabs(frm) {
    if (frm.is_new()) return;
    frm.set_df_property('custom_procedure_payment_status', 'hidden', 1);
    frm.set_df_property('custom_vaccination_payment_status', 'hidden', 1);
    setTimeout(function() {
        var proc_wrapper = frm.get_field('custom_procedures_html');
        var vacc_wrapper = frm.get_field('custom_vaccinations_html');
        if (!proc_wrapper || !vacc_wrapper) { console.warn('Vet tabs: HTML fields not ready'); return; }
        frappe.call({
            method: 'veterinary.veterinary.utils.get_quotation_medical_records',
            args: { quotation: frm.doc.name },
            callback: function(r) {
                if (!r.message) return;
                render_procedures_html(frm, r.message.procedures);
                render_vaccinations_html(frm, r.message.vaccinations);
            }
        });
    }, 600);
}

function render_procedures_html(frm, procs) {
    let html = `<div style="padding:15px;border:1px solid #d1d8dd;border-radius:8px;background:#fff;overflow-x:auto;"><h5 style="margin-top:0;color:#2980b9;border-bottom:2px solid #2980b9;padding-bottom:10px;">PROCEDURE RECORDS <button type="button" class="btn btn-xs btn-default pull-right" onclick="cur_frm.trigger('refresh')">Refresh</button></h5><table class="table table-bordered table-hover" style="margin-bottom:0;min-width:1900px;white-space:nowrap;"><thead style="background:#f0f7ff;"><tr><th style="width:80px;text-align:center;">Action</th><th style="width:180px;">Patient Name</th><th style="width:180px;">Patient Owner</th><th style="width:140px;">Doctor</th><th style="width:140px;">Start Time</th><th style="width:140px;">End Time</th><th style="width:140px;">Quotation</th><th style="width:120px;">Payment</th><th style="width:140px;">Medical Exam</th><th>Drug Items (Item | Qty | Dosage | Instructions)</th></tr></thead><tbody>`;
    if (procs && procs.length > 0) {
        procs.forEach(function(d) {
            let items_html = (d.items || []).map(function(i) { return `<div style="margin-bottom:4px;padding:4px 6px;border-left:3px solid #2980b9;background:#f8f9fa;font-size:0.88em;"><b>${i.drug_item || '-'}</b> | Qty:${i.quantity || 0} | Dose:${i.dosage || '-'} | ${i.instructions || '-'}</div>`; }).join('') || '<i class="text-muted">No drugs</i>';
            let bc = d.custom_payment_status === 'Fully Paid' ? 'success' : (d.custom_payment_status === 'Partly Paid' ? 'warning' : 'danger');
            html += `<tr><td style="text-align:center;"><button type="button" class="btn btn-xs btn-primary" onclick="window.open('/app/procedure/${d.name}','_blank')"><i class="fa fa-pencil"></i> Edit</button></td><td style="font-weight:bold;">${(d.pet && d.pet.patient_name) || d.patient_name || '-'}</td><td>${d.patient_owner || '-'}</td><td>${d.doctor_name || '-'}</td><td>${d.start_time ? frappe.datetime.global_date_format(d.start_time) : '-'}</td><td>${d.end_time ? frappe.datetime.global_date_format(d.end_time) : '-'}</td><td>${d.quotation || '-'}</td><td><span class="label label-${bc}">${d.custom_payment_status || 'Pending'}</span></td><td>${d.medical_examination || '-'}</td><td style="white-space:normal;">${items_html}</td></tr>`;
        });
    } else { html += '<tr><td colspan="10" class="text-center text-muted" style="padding:20px;">No procedure records found.</td></tr>'; }
    html += '</tbody></table></div>';
    frm.get_field('custom_procedures_html').$wrapper.html(html);
}

function render_vaccinations_html(frm, vacs) {
    let html = `<div style="padding:15px;border:1px solid #d1d8dd;border-radius:8px;background:#fff;overflow-x:auto;"><h5 style="margin-top:0;color:#27ae60;border-bottom:2px solid #27ae60;padding-bottom:10px;">VACCINATION RECORDS <button type="button" class="btn btn-xs btn-default pull-right" onclick="cur_frm.trigger('refresh')">Refresh</button></h5><table class="table table-bordered table-hover" style="margin-bottom:0;min-width:1700px;white-space:nowrap;"><thead style="background:#f0fff4;"><tr><th style="width:80px;text-align:center;">Action</th><th style="width:180px;">Patient Name</th><th style="width:140px;">Quotation</th><th style="width:120px;">Payment</th><th>Vaccination Items (Vaccine | Batch | Date | Status | Next Follow-up | User)</th></tr></thead><tbody>`;
    if (vacs && vacs.length > 0) {
        vacs.forEach(function(d) {
            let items_html = (d.items || []).map(function(i) { return `<div style="margin-bottom:4px;padding:4px 6px;border-left:3px solid #27ae60;background:#f8f9fa;font-size:0.88em;"><b>${i.vaccine || '-'}</b> | Batch:${i.batch || '-'} | Date:${i.date ? frappe.datetime.global_date_format(i.date) : '-'} | ${i.status || '-'} | Next:${i.next_follow_up_date ? frappe.datetime.global_date_format(i.next_follow_up_date) : '-'} | ${i.user || '-'}</div>`; }).join('') || '<i class="text-muted">No vaccines</i>';
            let bc = d.custom_payment_status === 'Fully Paid' ? 'success' : (d.custom_payment_status === 'Partly Paid' ? 'warning' : 'danger');
            html += `<tr><td style="text-align:center;"><button type="button" class="btn btn-xs btn-success" onclick="window.open('/app/vaccinations/${d.name}','_blank')"><i class="fa fa-pencil"></i> Edit</button></td><td style="font-weight:bold;">${(d.pet && d.pet.patient_name) || d.patient_name || '-'}</td><td>${d.quotation || '-'}</td><td><span class="label label-${bc}">${d.custom_payment_status || 'Pending'}</span></td><td style="white-space:normal;">${items_html}</td></tr>`;
        });
    } else { html += '<tr><td colspan="5" class="text-center text-muted" style="padding:20px;">No vaccination records found.</td></tr>'; }
    html += '</tbody></table></div>';
    frm.get_field('custom_vaccinations_html').$wrapper.html(html);
}

function toggle_pet_view(frm) {
    const is_group = frm.doc.custom_is_group;
    const original_fields = ['custom_patient_name','custom_colour','custom_sex','custom_date_of_birth','custom_hyd','custom_column_break_1','custom_differential_diagnosis','custom_species','custom_breed','custom_hr','custom_rr','custom_column_break_2','custom_medication_receipt_no','custom_weight','custom_crt','custom_medicals_section','custom_diagnosis','custom_advices','custom_column_break_3','custom_complaint','custom_patient_owner'];
    const inline_fields = ['custom_inline_section_patient','custom_inline_col1','custom_inline_patient_name','custom_inline_patient_owner','custom_inline_sex','custom_inline_col2','custom_inline_dob','custom_inline_species','custom_inline_follow_up','custom_inline_col3','custom_inline_breed','custom_inline_colour','custom_inline_section_exam','custom_inline_hyd','custom_inline_col4','custom_inline_weight','custom_inline_col5','custom_inline_crt','custom_inline_col6','custom_inline_rr','custom_inline_col7','custom_inline_hr','custom_inline_section_medicals','custom_inline_diff_diagnosis','custom_inline_diagnosis','custom_inline_col8','custom_inline_complaint','custom_inline_advices'];
    const table_fields = ['custom_section_break_fgfm3','custom_pet_details'];
    original_fields.forEach(f => frm.set_df_property(f, 'hidden', 1));
    inline_fields.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 1 : 0));
    table_fields.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 0 : 1));
    frm.set_df_property('custom_follow_up_date', 'hidden', is_group ? 0 : 1);
    frm.set_df_property('custom_inline_next_follow_up_date', 'hidden', is_group ? 1 : 0);
    frm.set_df_property('items', 'hidden', 1);
    frm.set_df_property('custom_procedures_tab', 'hidden', 0);
    frm.set_df_property('custom_vaccinations_tab', 'hidden', 0);
    frm.set_df_property('custom_procedures_html', 'hidden', 0);
    frm.set_df_property('custom_vaccinations_html', 'hidden', 0);
    frm.set_df_property('custom_is_admitted', 'hidden', 0);
    toggle_admissions(frm);
    frm.refresh_fields();
}

function toggle_admissions(frm) {
    const is_group = frm.doc.custom_is_group;
    const is_admitted = frm.doc.custom_is_admitted;
    const table_adm = ['custom_admissions_section','custom_admissions_table'];
    const inline_adm = ['custom_inline_admissions_section','custom_inline_adm_patient','custom_inline_adm_bed','custom_inline_adm_col1','custom_inline_adm_doctor','custom_inline_adm_checkin','custom_inline_adm_col2','custom_inline_adm_checkout'];
    if (is_admitted) {
        table_adm.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 0 : 1));
        inline_adm.forEach(f => frm.set_df_property(f, 'hidden', is_group ? 1 : 0));
    } else {
        table_adm.forEach(f => frm.set_df_property(f, 'hidden', 1));
        inline_adm.forEach(f => frm.set_df_property(f, 'hidden', 1));
    }
}

function update_medication_filters(frm) {
    if (frm.doc.customer_name) { frm.set_query('custom_medication_receipt_no', function() { return { filters: { customer: frm.doc.customer_name, docstatus: 1 } }; }); }
}

function reset_patient_filters(frm) {
    if (frm.doc.custom_pet_details) { frm.doc.custom_pet_details.forEach(row => { row.patient_name = ''; }); frm.refresh_field('custom_pet_details'); }
    frm.fields_dict['custom_pet_details'].grid.get_field('patient_name').get_query = function() { return { filters: { patient_owner: frm.doc.party_name } }; };
}

function fetch_patient_details(frm) {
    if (frm.doc.custom_inline_patient_name) { frappe.db.get_doc('Patient Name', frm.doc.custom_inline_patient_name).then(doc => { frm.set_value('custom_inline_patient_owner', doc.patient_owner); frm.set_value('custom_inline_sex', doc.sex); frm.set_value('custom_inline_dob', doc.dob); frm.set_value('custom_inline_species', doc.species); frm.set_value('custom_inline_breed', doc.breed); frm.set_value('custom_inline_colour', doc.colour); }); }
}

frappe.ui.form.on('Pet Details', {
    patient_name: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.patient_name) { frappe.db.get_doc('Patient Name', row.patient_name).then(doc => { frappe.model.set_value(cdt, cdn, 'patient_owner', doc.patient_owner); frappe.model.set_value(cdt, cdn, 'sex', doc.sex); frappe.model.set_value(cdt, cdn, 'date_of_birth', doc.dob); frappe.model.set_value(cdt, cdn, 'species', doc.species); frappe.model.set_value(cdt, cdn, 'breed', doc.breed); frappe.model.set_value(cdt, cdn, 'colour', doc.colour); }); }
    }
});

frappe.ui.form.on('Patient Name', {

    // Trigger on form load and whenever "vaccinated" changes
    refresh: function(frm) {
        toggle_vaccine_date(frm);
    },

    vaccinated: function(frm) {
        toggle_vaccine_date(frm);
    }

});

// Helper function
function toggle_vaccine_date(frm) {
    if (frm.doc.vaccinated) {
        frm.set_df_property('next_vaccination_date', 'hidden', 0);  // show
    } else {
        frm.set_df_property('next_vaccination_date', 'hidden', 1);  // hide
        frm.set_value('next_vaccination_date', null);               // clear value
    }
}

frappe.ui.form.on('Patient Name', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button('View Medical History', function() {

                // 1️⃣ Inject filters
                frappe.route_options = {
                    patient_owner: frm.doc.pet_owner,
                    patient_name: frm.doc.patient_name
                };

                // 2️⃣ Navigate
                frappe.set_route('query-report', 'Patient Medical History');
            });
        }
    }
});

frappe.ui.form.on('Patient Name', {
    refresh: function(frm) {
        // Render preview on refresh
        render_image_preview(frm);
    },
    photo: function(frm) {
        // Update preview whenever image changes
        render_image_preview(frm);
    }
});

function render_image_preview(frm) {
    const field = frm.fields_dict.image_preview.$wrapper;
    const file_url = frm.doc.image; // this is the file URL

    if (file_url) {
        field.html(`<img src="${file_url}" style="max-width:200px; max-height:200px; border:1px solid #ccc; padding:4px;">`);
    } else {
        field.html('<p>No image attached</p>');
    }
}

frappe.ui.form.on('Post Mortem Report', {
    refresh: function(frm) {
        render_image_previews(frm);
    },
    image1: function(frm) { render_image_previews(frm); },
    image2: function(frm) { render_image_previews(frm); },
    image3: function(frm) { render_image_previews(frm); }
});

function render_image_previews(frm) {
    const images = ['image1', 'image2', 'image3'];
    const previews = ['image_preview1', 'image_preview2', 'image_preview3']; // FIXED

    images.forEach((img_field, index) => {
        const preview_field = previews[index];
        const field = frm.fields_dict[preview_field].$wrapper;
        const file_url = frm.doc[img_field];

        if (file_url) {
            field.html(`<img src="${file_url}" style="max-width:200px; max-height:200px; border:1px solid #ccc; padding:4px;">`);
        } else {
            field.html('<p>No image attached</p>');
        }
    });
}
